from pathlib import Path
import re

root = Path('site')
index = (root/'index.html').read_text(encoding='utf-8')
template_head = index.split('<main')[0]
template_tail = index.split('</main>')[1]
arrow = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M5 19 19 5M5 5h14v14"/></svg>'

def page(name, title, body):
    head = re.sub(r'<title>.*?</title>', '<title>'+title+' · Nident</title>', template_head)
    head = head.replace('class="current" href="index.html" aria-current="page"','href="index.html"')
    (root/name).write_text(head+'<main id="contenido" class="wrap">'+body+'</main>'+template_tail,encoding='utf-8')

def field(label,name,extra='',tag='input'):
    if tag=='input': control=f'<input id="{name}" name="{name}" {extra}>'
    elif tag=='textarea': control=f'<textarea id="{name}" name="{name}" {extra}></textarea>'
    else: control=f'<select id="{name}" name="{name}" required>{extra}</select>'
    return f'<label class="claim-field" for="{name}"><span>{label}</span>{control}</label>'

